def bracketed_wargear_becomes_accessories(apps, schema_editor):
    """Anything already authored with a fits_* bracket was an accessory
    wearing wargear's clothes, so it moves rather than being stranded.
    Plain wargear stays wargear: nothing about it said otherwise.
    """
    Wargear = apps.get_model("library", "Wargear")
    WeaponAccessory = apps.get_model("library", "WeaponAccessory")
    moving = Wargear.objects.exclude(fits_category__isnull=True, fits_asterisked=False)
    for wargear in moving:
        WeaponAccessory.objects.create(
            **{field: getattr(wargear, field) for field in _CARRIED}
        )
    moving.delete()


def accessories_become_wargear(apps, schema_editor):
    Wargear = apps.get_model("library", "Wargear")
    WeaponAccessory = apps.get_model("library", "WeaponAccessory")
    for accessory in WeaponAccessory.objects.all():
        Wargear.objects.create(
            **{field: getattr(accessory, field) for field in _CARRIED}
        )
    WeaponAccessory.objects.all().delete()


